#!/usr/bin/env python3\n\"\"\"\nMain Application - ECG Doppler Simulation System\n\nProgram interaktif untuk menjalankan simulasi ECG dan Doppler.\n\"\"\"\n\nimport numpy as np\nimport matplotlib.pyplot as plt\nfrom ecg_simulator import ECGSimulator\nfrom doppler_simulator import DopplerSimulator\nfrom signal_processor import SignalProcessor\nfrom visualizer import Visualizer\nimport sys\n\n\ndef print_menu():\n    \"\"\"\n    Tampilkan menu utama.\n    \"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"     ECG DOPPLER SIMULATION SYSTEM\")\n    print(\"=\"*60)\n    print(\"\\n1. ECG Simulation\")\n    print(\"   1.1 - Normal ECG\")\n    print(\"   1.2 - ECG dengan Aritmia\")\n    print(\"   1.3 - Analisis Statistik ECG\")\n    print(\"\\n2. Doppler Simulation\")\n    print(\"   2.1 - Doppler Normal (Pulsatile)\")\n    print(\"   2.2 - Doppler Konstan\")\n    print(\"   2.3 - Doppler Turbulen\")\n    print(\"   2.4 - Analisis Spektrum Doppler\")\n    print(\"\\n3. Signal Processing\")\n    print(\"   3.1 - Apply Filter\")\n    print(\"   3.2 - Remove Baseline Wander\")\n    print(\"   3.3 - Analisis Frekuensi (FFT)\")\n    print(\"   3.4 - Deteksi Peak\")\n    print(\"\\n4. Perbandingan Sinyal\")\n    print(\"   4.1 - ECG Normal vs Aritmia\")\n    print(\"   4.2 - Doppler Normal vs Turbulen\")\n    print(\"\\n5. Export Data\")\n    print(\"   5.1 - Simpan ECG ke CSV\")\n    print(\"   5.2 - Simpan Doppler ke CSV\")\n    print(\"\\n6. Exit\")\n    print(\"\\n\" + \"=\"*60)\n\n\ndef run_ecg_normal():\n    \"\"\"\n    Jalankan simulasi ECG normal.\n    \"\"\"\n    print(\"\\n>>> ECG Normal Simulation\")\n    print(\"-\" * 40)\n    \n    # Input parameter\n    try:\n        hr = float(input(\"Masukkan heart rate (bpm) [default: 72]: \") or 72)\n        duration = float(input(\"Masukkan durasi (detik) [default: 10]: \") or 10)\n    except ValueError:\n        print(\"Input tidak valid! Menggunakan default.\")\n        hr, duration = 72, 10\n    \n    # Generate ECG\n    ecg = ECGSimulator(heart_rate=hr, duration=duration)\n    signal = ecg.generate_signal()\n    stats = ecg.get_statistics()\n    \n    # Tampilkan statistik\n    print(\"\\n--- Statistik ECG ---\")\n    print(f\"Heart Rate: {stats['heart_rate']:.1f} bpm\")\n    print(f\"Jumlah Beats: {stats['num_beats']}\")\n    print(f\"HRV (Heart Rate Variability): {stats['hrv']:.4f}\")\n    print(f\"Signal Min: {stats['signal_min']:.4f} mV\")\n    print(f\"Signal Max: {stats['signal_max']:.4f} mV\")\n    print(f\"Signal Mean: {stats['signal_mean']:.4f} mV\")\n    print(f\"Signal Std Dev: {stats['signal_std']:.4f} mV\")\n    \n    # Plot\n    show_plot = input(\"\\nTampilkan grafik? (y/n) [y]: \") or \"y\"\n    if show_plot.lower() == 'y':\n        ecg.plot(show_peaks=True)\n    \n    return ecg, signal, stats\n\n\ndef run_ecg_arrhythmia():\n    \"\"\"\n    Jalankan simulasi ECG dengan aritmia.\n    \"\"\"\n    print(\"\\n>>> ECG dengan Aritmia\")\n    print(\"-\" * 40)\n    \n    try:\n        hr = float(input(\"Masukkan heart rate (bpm) [default: 72]: \") or 72)\n        duration = float(input(\"Masukkan durasi (detik) [default: 10]: \") or 10)\n    except ValueError:\n        print(\"Input tidak valid!\")\n        return\n    \n    # Tipe aritmia\n    print(\"\\nTipe Aritmia:\")\n    print(\"1. Premature Beat\")\n    print(\"2. Pause\")\n    print(\"3. Flutter\")\n    \n    arrhythmia_choice = input(\"Pilih (1-3) [1]: \") or \"1\"\n    arrhythmia_map = {\"1\": \"premature_beat\", \"2\": \"pause\", \"3\": \"flutter\"}\n    arrhythmia_type = arrhythmia_map.get(arrhythmia_choice, \"premature_beat\")\n    \n    # Generate ECG\n    ecg = ECGSimulator(heart_rate=hr, duration=duration)\n    signal_normal = ecg.generate_signal()\n    \n    # Tambah aritmia\n    signal_arrhythmia = ecg.add_arrhythmia(arrhythmia_type, position=0.5)\n    \n    print(f\"\\n--- Aritmia: {arrhythmia_type} ---\")\n    print(f\"Position: 50% dari durasi\")\n    \n    # Tampilkan perbandingan\n    show_plot = input(\"Tampilkan grafik? (y/n) [y]: \") or \"y\"\n    if show_plot.lower() == 'y':\n        ecg.plot(show_peaks=True, arrhythmia_signal=signal_arrhythmia)\n    \n    return ecg, signal_arrhythmia\n\n\ndef run_ecg_statistics():\n    \"\"\"\n    Jalankan analisis statistik ECG.\n    \"\"\"\n    print(\"\\n>>> Analisis Statistik ECG\")\n    print(\"-\" * 40)\n    \n    try:\n        hr = float(input(\"Masukkan heart rate (bpm) [default: 72]: \") or 72)\n        duration = float(input(\"Masukkan durasi (detik) [default: 10]: \") or 10)\n    except ValueError:\n        print(\"Input tidak valid!\")\n        return\n    \n    ecg = ECGSimulator(heart_rate=hr, duration=duration)\n    signal = ecg.generate_signal()\n    stats = ecg.get_statistics()\n    \n    print(\"\\n--- Statistik Lengkap ECG ---\")\n    for key, value in stats.items():\n        if isinstance(value, (list, np.ndarray)):\n            if len(value) > 0:\n                print(f\"{key}: mean={np.mean(value):.4f}, std={np.std(value):.4f}\")\n        else:\n            print(f\"{key}: {value:.4f}\")\n    \n    # Visualisasi statistik\n    show_vis = input(\"\\nVisualkan statistik dalam chart? (y/n) [y]: \") or \"y\"\n    if show_vis.lower() == 'y':\n        numeric_stats = {k: v for k, v in stats.items() \n                        if isinstance(v, (int, float, np.number))}\n        Visualizer.plot_statistics(numeric_stats, title=\"ECG Statistics\")\n\n\ndef run_doppler_simulation(profile_type='pulsatile'):\n    \"\"\"\n    Jalankan simulasi Doppler.\n    \n    Args:\n        profile_type: Tipe profil ('pulsatile', 'constant', 'turbulent')\n    \"\"\"\n    print(f\"\\n>>> Doppler Simulation - {profile_type.upper()}\")\n    print(\"-\" * 40)\n    \n    try:\n        freq = float(input(\"Masukkan carrier frequency (MHz) [default: 2]: \") or 2) * 1e6\n        duration = float(input(\"Masukkan durasi (detik) [default: 5]: \") or 5)\n        velocity = float(input(\"Masukkan max velocity (cm/s) [default: 50]: \") or 50) / 100\n    except ValueError:\n        print(\"Input tidak valid!\")\n        return\n    \n    # Generate Doppler\n    doppler = DopplerSimulator(carrier_frequency=freq, duration=duration, \n                               max_velocity=velocity)\n    signal = doppler.generate_signal(profile_type)\n    stats = doppler.get_statistics()\n    \n    # Tampilkan statistik\n    print(f\"\\n--- Statistik Doppler ({profile_type}) ---\")\n    print(f\"Mean Velocity: {stats['mean_velocity']*100:.1f} cm/s\")\n    print(f\"Max Velocity: {stats['max_velocity']*100:.1f} cm/s\")\n    print(f\"Min Velocity: {stats['min_velocity']*100:.1f} cm/s\")\n    print(f\"Velocity Std Dev: {stats['velocity_std']*100:.1f} cm/s\")\n    print(f\"Mean Doppler Shift: {stats['mean_doppler_shift']/1e3:.1f} kHz\")\n    print(f\"Max Doppler Shift: {stats['max_doppler_shift']/1e3:.1f} kHz\")\n    \n    # Plot\n    show_plot = input(\"\\nTampilkan grafik? (y/n) [y]: \") or \"y\"\n    if show_plot.lower() == 'y':\n        doppler.plot(show_velocity=True, show_spectrum=True)\n    \n    return doppler, signal, stats\n\n\ndef run_signal_filtering():\n    \"\"\"\n    Jalankan filter pada sinyal.\n    \"\"\"\n    print(\"\\n>>> Signal Filtering\")\n    print(\"-\" * 40)\n    \n    # Generate test signal\n    print(\"\\nGenerating test ECG signal...\")\n    ecg = ECGSimulator(heart_rate=72, duration=5)\n    signal = ecg.generate_signal()\n    t = ecg.t\n    sampling_rate = ecg.sampling_rate\n    \n    # Pilih filter\n    print(\"\\nJenis Filter:\")\n    print(\"1. Lowpass\")\n    print(\"2. Highpass\")\n    print(\"3. Bandpass\")\n    \n    filter_choice = input(\"Pilih (1-3) [3]: \") or \"3\"\n    \n    try:\n        if filter_choice == \"1\":\n            cutoff = float(input(\"Masukkan cutoff frequency (Hz) [40]: \") or 40)\n            filtered = SignalProcessor.apply_lowpass_filter(signal, cutoff, sampling_rate)\n            title = f\"Lowpass Filter (cutoff: {cutoff} Hz)\"\n        elif filter_choice == \"2\":\n            cutoff = float(input(\"Masukkan cutoff frequency (Hz) [0.5]: \") or 0.5)\n            filtered = SignalProcessor.apply_highpass_filter(signal, cutoff, sampling_rate)\n            title = f\"Highpass Filter (cutoff: {cutoff} Hz)\"\n        else:\n            low_freq = float(input(\"Masukkan low frequency (Hz) [1]: \") or 1)\n            high_freq = float(input(\"Masukkan high frequency (Hz) [40]: \") or 40)\n            filtered = SignalProcessor.apply_bandpass_filter(signal, low_freq, high_freq, sampling_rate)\n            title = f\"Bandpass Filter ({low_freq}-{high_freq} Hz)\"\n    except ValueError:\n        print(\"Input tidak valid!\")\n        return\n    \n    # Plot comparison\n    Visualizer.plot_comparison(t, signal, filtered, \n                              label1=\"Original Signal\",\n                              label2=\"Filtered Signal\",\n                              title=title)\n\n\ndef run_fft_analysis():\n    \"\"\"\n    Jalankan analisis FFT.\n    \"\"\"\n    print(\"\\n>>> FFT Analysis\")\n    print(\"-\" * 40)\n    \n    # Generate ECG signal\n    ecg = ECGSimulator(heart_rate=72, duration=10)\n    signal = ecg.generate_signal()\n    sampling_rate = ecg.sampling_rate\n    \n    # Compute FFT\n    freqs, magnitude = SignalProcessor.compute_fft(signal, sampling_rate)\n    \n    # Compute PSD\n    freqs_psd, psd = SignalProcessor.compute_power_spectrum(signal, sampling_rate)\n    \n    print(\"\\n--- Analisis Frekuensi ---\")\n    print(f\"Peak Frequency: {freqs[np.argmax(magnitude[1:])+1]:.2f} Hz\")\n    print(f\"Peak Magnitude: {np.max(magnitude):.4f}\")\n    print(f\"PSD Peak: {np.max(psd):.4f}\")\n    \n    # Plot\n    fig, axes = plt.subplots(2, 1, figsize=(12, 8))\n    \n    # FFT\n    axes[0].plot(freqs, magnitude, 'b-', linewidth=1)\n    axes[0].set_xlabel('Frequency (Hz)')\n    axes[0].set_ylabel('Magnitude')\n    axes[0].set_title('FFT Spectrum')\n    axes[0].set_xlim([0, 50])\n    axes[0].grid(True, alpha=0.3)\n    \n    # PSD\n    axes[1].plot(freqs_psd, psd, 'g-', linewidth=1)\n    axes[1].set_xlabel('Frequency (Hz)')\n    axes[1].set_ylabel('Power (dB/Hz)')\n    axes[1].set_title('Power Spectral Density')\n    axes[1].set_xlim([0, 50])\n    axes[1].grid(True, alpha=0.3)\n    \n    plt.tight_layout()\n    plt.show()\n\n\ndef run_peak_detection():\n    \"\"\"\n    Jalankan deteksi peak.\n    \"\"\"\n    print(\"\\n>>> Peak Detection\")\n    print(\"-\" * 40)\n    \n    # Generate ECG\n    ecg = ECGSimulator(heart_rate=72, duration=10)\n    signal = ecg.generate_signal()\n    t = ecg.t\n    \n    # Deteksi peak\n    peaks = SignalProcessor.detect_peaks(signal, \n                                        height=np.max(signal)*0.3,\n                                        distance=int(ecg.sampling_rate*0.3))\n    \n    # Plot\n    plt.figure(figsize=(14, 6))\n    plt.plot(t, signal, 'b-', linewidth=1.5, label='ECG Signal')\n    plt.plot(t[peaks], signal[peaks], 'rx', markersize=10, label=f'Peaks ({len(peaks)})')\n    plt.xlabel('Time (s)')\n    plt.ylabel('Amplitude (mV)')\n    plt.title('Peak Detection')\n    plt.legend()\n    plt.grid(True, alpha=0.3)\n    plt.tight_layout()\n    plt.show()\n    \n    print(f\"\\n--- Hasil Deteksi ---\")\n    print(f\"Jumlah Peak Terdeteksi: {len(peaks)}\")\n    print(f\"Rata-rata Interval: {np.mean(np.diff(peaks))/ecg.sampling_rate:.2f} s\")\n\n\ndef run_comparison_ecg():\n    \"\"\"\n    Bandingkan ECG normal vs aritmia.\n    \"\"\"\n    print(\"\\n>>> ECG Normal vs Aritmia\")\n    print(\"-\" * 40)\n    \n    # Generate kedua sinyal\n    ecg = ECGSimulator(heart_rate=72, duration=10)\n    signal_normal = ecg.generate_signal()\n    signal_arrhythmia = ecg.add_arrhythmia('premature_beat', position=0.5)\n    \n    # Perbandingan\n    Visualizer.plot_comparison(ecg.t, signal_normal, signal_arrhythmia,\n                              label1=\"Normal ECG\",\n                              label2=\"ECG dengan Premature Beat\",\n                              title=\"ECG Comparison\")\n\n\ndef run_comparison_doppler():\n    \"\"\"\n    Bandingkan Doppler normal vs turbulen.\n    \"\"\"\n    print(\"\\n>>> Doppler Normal vs Turbulen\")\n    print(\"-\" * 40)\n    \n    # Generate kedua sinyal\n    doppler = DopplerSimulator(duration=3)\n    signal_pulsatile = doppler.generate_signal('pulsatile')\n    signal_turbulent = doppler.generate_signal('turbulent')\n    \n    # Perbandingan kecepatan\n    velocity_pulsatile = doppler.generate_velocity_profile('pulsatile')\n    velocity_turbulent = doppler.generate_velocity_profile('turbulent')\n    \n    # Plot\n    Visualizer.plot_comparison(doppler.t, velocity_pulsatile*100, \n                              velocity_turbulent*100,\n                              label1=\"Pulsatile Flow\",\n                              label2=\"Turbulent Flow\",\n                              title=\"Blood Flow Velocity Comparison\")\n\n\ndef export_ecg_csv():\n    \"\"\"\n    Ekspor ECG ke CSV.\n    \"\"\"\n    print(\"\\n>>> Export ECG to CSV\")\n    print(\"-\" * 40)\n    \n    try:\n        filename = input(\"Masukkan nama file [ecg_data.csv]: \") or \"ecg_data.csv\"\n        hr = float(input(\"Heart rate (bpm) [72]: \") or 72)\n        duration = float(input(\"Duration (s) [10]: \") or 10)\n    except ValueError:\n        print(\"Input tidak valid!\")\n        return\n    \n    # Generate\n    ecg = ECGSimulator(heart_rate=hr, duration=duration)\n    signal = ecg.generate_signal()\n    peaks, stats = ecg.detect_peaks()\n    \n    # Save\n    import csv\n    with open(filename, 'w', newline='') as f:\n        writer = csv.writer(f)\n        writer.writerow(['Time (s)', 'ECG Signal (mV)', 'Peak'])\n        \n        for i, (t, sig) in enumerate(zip(ecg.t, signal)):\n            is_peak = 'Yes' if i in peaks else 'No'\n            writer.writerow([f\"{t:.4f}\", f\"{sig:.6f}\", is_peak])\n    \n    print(f\"\\n✓ Data tersimpan ke: {filename}\")\n    print(f\"  Total samples: {len(signal)}\")\n    print(f\"  Total peaks: {len(peaks)}\")\n\n\ndef export_doppler_csv():\n    \"\"\"\n    Ekspor Doppler ke CSV.\n    \"\"\"\n    print(\"\\n>>> Export Doppler to CSV\")\n    print(\"-\" * 40)\n    \n    try:\n        filename = input(\"Masukkan nama file [doppler_data.csv]: \") or \"doppler_data.csv\"\n        duration = float(input(\"Duration (s) [5]: \") or 5)\n        profile = input(\"Profile (pulsatile/constant/turbulent) [pulsatile]: \") or \"pulsatile\"\n    except ValueError:\n        print(\"Input tidak valid!\")\n        return\n    \n    # Generate\n    doppler = DopplerSimulator(duration=duration)\n    signal = doppler.generate_signal(profile)\n    velocity = doppler.generate_velocity_profile(profile)\n    \n    # Save\n    import csv\n    with open(filename, 'w', newline='') as f:\n        writer = csv.writer(f)\n        writer.writerow(['Time (s)', 'Velocity (cm/s)', 'Doppler Signal'])\n        \n        for t, v, sig in zip(doppler.t, velocity*100, signal):\n            writer.writerow([f\"{t:.4f}\", f\"{v:.4f}\", f\"{sig:.6f}\"])\n    \n    print(f\"\\n✓ Data tersimpan ke: {filename}\")\n    print(f\"  Total samples: {len(signal)}\")\n    print(f\"  Profile: {profile}\")\n\n\ndef main():\n    \"\"\"\n    Main application loop.\n    \"\"\"\n    while True:\n        try:\n            print_menu()\n            choice = input(\"Pilih menu (contoh: 1.1, 2.3, 5): \").strip()\n            \n            # ECG Menu\n            if choice == \"1.1\":\n                run_ecg_normal()\n            elif choice == \"1.2\":\n                run_ecg_arrhythmia()\n            elif choice == \"1.3\":\n                run_ecg_statistics()\n            \n            # Doppler Menu\n            elif choice == \"2.1\":\n                run_doppler_simulation('pulsatile')\n            elif choice == \"2.2\":\n                run_doppler_simulation('constant')\n            elif choice == \"2.3\":\n                run_doppler_simulation('turbulent')\n            elif choice == \"2.4\":\n                run_fft_analysis()\n            \n            # Signal Processing Menu\n            elif choice == \"3.1\":\n                run_signal_filtering()\n            elif choice == \"3.2\":\n                print(\"\\n>>> Remove Baseline Wander\")\n                ecg = ECGSimulator(duration=5)\n                signal = ecg.generate_signal()\n                signal_corrected = SignalProcessor.remove_baseline_wander(signal, 500)\n                Visualizer.plot_comparison(ecg.t, signal, signal_corrected,\n                                          label1=\"Original\", label2=\"Baseline Removed\")\n            elif choice == \"3.3\":\n                run_fft_analysis()\n            elif choice == \"3.4\":\n                run_peak_detection()\n            \n            # Comparison Menu\n            elif choice == \"4.1\":\n                run_comparison_ecg()\n            elif choice == \"4.2\":\n                run_comparison_doppler()\n            \n            # Export Menu\n            elif choice == \"5.1\":\n                export_ecg_csv()\n            elif choice == \"5.2\":\n                export_doppler_csv()\n            \n            elif choice == \"6\":\n                print(\"\\nTerima kasih telah menggunakan ECG Doppler Simulation System!\")\n                print(\"Goodbye!\\n\")\n                break\n            \n            else:\n                print(\"\\n⚠ Menu tidak ditemukan. Silakan coba lagi.\")\n            \n            # Tanya untuk lanjut atau tidak\n            input(\"\\nTekan Enter untuk melanjutkan...\")\n            \n        except KeyboardInterrupt:\n            print(\"\\n\\nProgram dihentikan oleh pengguna.\")\n            break\n        except Exception as e:\n            print(f\"\\n⚠ Error: {e}\")\n            print(\"Silakan coba lagi.\")\n\n\nif __name__ == \"__main__\":\n    main()\n